18	    focus: { value: 100 }, aper: { value: 4 }, maxCoc: { value: 24 }, near: { value: .1 }, far: { value: 5000 },
19	    srcRes: { value: new THREE.Vector2(3840, 2160) },
20	    bandY: { value: .5 }, bandW: { value: .08 }, bandAmp: { value: 30 }, bandMix: { value: .5 }, bandTilt: { value: 0 }, bandPow: { value: 1.3 },
