22	  vertexShader: VS,
23	  fragmentShader: `
24	    #include <packing>
25	    varying vec2 vUv; uniform sampler2D tColor, tDepth, tAO; uniform vec2 srcRes;
26	    uniform float aoAmt, focus, aper, maxCoc, near, far, bandY, bandW, bandAmp, bandMix, bandTilt, bandPow;
27	    float cocAt(vec2 uv){
28	      float d = texture2D(tDepth, uv).x;
29	      float z = -perspectiveDepthToViewZ(d, near, far);
