55	      // Maximum blur around this pixel (the foreground must be able to blur over sharp objects)
56	      vec3 acc = c0.rgb / (a0*a0 + 1.); float wsum = 1. / (a0*a0 + 1.);
57	      float rot = h12(gl_FragCoord.xy) * 6.2832;
58	      const int N = 128;
