90	      this.ao.updatePdMaterial({ lumaPhi: 10, depthPhi: 2, normalPhi: 3, radius: 4 * s, rings: 2, samples: 16 });
91	      this.aoAmt = o.aoAmt ?? .8;
92	    }
93	  }
94	  render(renderer, writeBuffer) {
95	    renderer.setRenderTarget(this.rt); renderer.clear(); renderer.render(this.scene, this.camera);
96	    if (this.ao && this.aoAmt > 0) this.ao.render(renderer, null, null);
97	    const u = this.coc.material.uniforms, b = this.band;
98	    u.tColor.value = this.rt.texture; u.tDepth.value = this.rt.depthTexture; u.focus.value = this.focus; u.aper.value = this.aper; u.maxCoc.value = this.maxCoc;
99	    u.near.value = this.camera.near; u.far.value = this.camera.far;
100	    u.bandY.value = b.y; u.bandW.value = b.w; u.bandAmp.value = b.amp; u.bandMix.value = b.mix; u.bandTilt.value = b.tilt; u.bandPow.value = b.pow;
101	    u.tAO.value = this.ao ? this.ao.gtaoMap : null; u.aoAmt.value = this.ao ? this.aoAmt : 0;
102	    renderer.setRenderTarget(this.rtC); this.coc.render(renderer);
103	    const g = this.gat.material.uniforms; g.tIn.value = this.rtC.texture; g.maxCoc.value = this.maxCoc;
