108	const gradeShader = {
109	  uniforms: { tDiffuse: { value: null }, amt: { value: .3 }, fade: { value: 1 }, warm: { value: 0 }, contrast: { value: .3 }, sat: { value: 1.35 }, lift: { value: 0 }, tint: { value: new THREE.Vector3(1, 1, 1) }, expo: { value: 1 } },
110	  vertexShader: `varying vec2 vUv; void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.); }`,
111	  fragmentShader: `varying vec2 vUv; uniform sampler2D tDiffuse; uniform float amt, fade, warm, contrast, sat, lift, expo; uniform vec3 tint;
112	    void main(){ vec4 c = texture2D(tDiffuse, vUv); c.rgb = max(c.rgb, 0.) * expo;
113	      vec2 d = vUv - .5; d.x *= 1.3; float v = 1. - amt * smoothstep(.2, .9, length(d));
114	      c.rgb *= v * fade; c.rgb *= mix(vec3(1.), vec3(1.07, 1., .88), warm) * tint;
115	      float l = dot(c.rgb, vec3(.2126, .7152, .0722)); c.rgb = max(mix(vec3(l), c.rgb, sat), 0.);
116	      c.rgb = c.rgb * (1. + contrast) / (1. + contrast * c.rgb / (c.rgb + .5));
117	      c.rgb += lift * (1. - c.rgb) * .06;
118	      gl_FragColor = c; }`
