121	export function makePost(renderer, scene, camera, w, h, o = {}) {
122	  const composer = new EffectComposer(renderer, new THREE.WebGLRenderTarget(w, h, { type: THREE.HalfFloatType }));
123	  const dof = new TiltPass(scene, camera, w, h, o);
124	  const bloom = new UnrealBloomPass(new THREE.Vector2(w, h), .25, .6, 1.2);
125	  const grade = new ShaderPass(gradeShader);
126	  const out = new OutputPass();
127	  composer.addPass(dof); composer.addPass(bloom); composer.addPass(grade); composer.addPass(out);
