"""Sound for v3: score, foley, ambience and voice, all placed from timeline.py and the beats' events.json.
    python sound.py            -> audio_v3/{music,foley,amb,vo,mix}.wav + audio_v3/cues.json, and a cue check
Three layers (ambience, foley, music) + voice. Music is ducked 8 dB under the voice. Silences S1/S2 have no music.
Everything is synthesised here (tuned mallets, noise foley), so the film carries no third-party audio."""
import json, os, subprocess, sys
import numpy as np
from scipy.signal import butter, sosfilt
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import timeline as TL
from vo_tools import FF, VO, dur

HERE = os.path.dirname(os.path.abspath(__file__))
FR = os.path.join(HERE, "frames_v3")
OUT = os.path.join(HERE, "audio_v3")
os.makedirs(OUT, exist_ok=True)
SR = 48000
N = int(TL.TOTAL / TL.FPS * SR) + SR
rng = np.random.default_rng(11)

def sec(frame):
    return frame / TL.FPS

def t_arr(d):
    return np.arange(int(d * SR)) / SR

def bp(x, lo, hi, order=2):
    return sosfilt(butter(order, [lo, hi], "bandpass", fs=SR, output="sos"), x)

def lp(x, f, order=2):
    return sosfilt(butter(order, f, "lowpass", fs=SR, output="sos"), x)

def hp(x, f, order=2):
    return sosfilt(butter(order, f, "highpass", fs=SR, output="sos"), x)

def add(buf, x, at_s, gain=1.0):
    i = int(at_s * SR)
    if i >= len(buf) or i + len(x) <= 0:
        return
    x = x[max(0, -i):]
    i = max(0, i)
    n = min(len(x), len(buf) - i)
    buf[i:i + n] += gain * x[:n]

def db(v):
    return 10 ** (v / 20)

# ---------------------------------------------------------------- instruments
NOTE = {"C": 0, "D": 2, "E": 4, "F": 5, "G": 7, "A": 9, "B": 11}
def hz(name):
    n, octv = name[:-1], int(name[-1])
    semi = NOTE[n[0]] + (1 if "#" in n else -1 if n.endswith("b") else 0)
    return 440.0 * 2 ** ((semi + 12 * (octv + 1) - 69) / 12)

def env(d, a=0.003, k=4.0):
    t = t_arr(d)
    e = np.exp(-t * k)
    e[: int(a * SR)] *= np.linspace(0, 1, int(a * SR))
    return t, e

def marimba(f, d=0.9, vel=1.0):
    t, e = env(d, 0.002, 3.0 + f / 300)
    x = np.sin(2 * np.pi * f * t) + 0.25 * np.sin(2 * np.pi * 3.93 * f * t) * np.exp(-t * 18) \
        + 0.08 * np.sin(2 * np.pi * 9.2 * f * t) * np.exp(-t * 40)
    return vel * x * e

def glock(f, d=1.6, vel=1.0):
    t, e = env(d, 0.001, 2.2)
    x = np.sin(2 * np.pi * f * t) + 0.35 * np.sin(2 * np.pi * 2.76 * f * t) * np.exp(-t * 6) \
        + 0.15 * np.sin(2 * np.pi * 5.4 * f * t) * np.exp(-t * 12)
    return vel * x * e

def vibe(f, d=2.4, vel=1.0):
    t, e = env(d, 0.004, 1.3)
    x = (np.sin(2 * np.pi * f * t) + 0.2 * np.sin(2 * np.pi * 4 * f * t) * np.exp(-t * 5)) * (1 + 0.25 * np.sin(2 * np.pi * 5.2 * t))
    return vel * x * e

def bass(f, d=1.2, vel=1.0):
    t, e = env(d, 0.01, 2.0)
    return vel * (np.sin(2 * np.pi * f * t) + 0.3 * np.sin(4 * np.pi * f * t)) * e

def musicbox(f, d=1.4, vel=1.0):
    t, e = env(d, 0.001, 3.0)
    return vel * (np.sin(2 * np.pi * f * t) + 0.3 * np.sin(2 * np.pi * 3 * f * t) * np.exp(-t * 8)) * e

def woodblock(f=1800, d=0.05, vel=1.0):
    t, e = env(d, 0.0005, 70)
    return vel * (np.sin(2 * np.pi * f * t) + 0.3 * rng.standard_normal(len(t))) * e

# ---------------------------------------------------------------- score
BEAT_S = 60 / TL.BPM
PROG = [("D", ["D4", "F4", "A4", "C5"], "D2"), ("Bb", ["Bb3", "D4", "F4", "A4"], "Bb1"),
        ("F", ["F4", "A4", "C5", "E5"], "F2"), ("C", ["C4", "E4", "G4", "Bb4"], "C2")]
MOTIF = [["A5", "F5"], ["G5", "D5"], ["F5", "C5"], ["E5", "G5"]]

def bars_in(f0, f1):
    b = int(np.ceil(f0 / TL.BAR))
    while b * TL.BAR < f1:
        yield b
        b += 1

def build_music(events):
    m = np.zeros(N)
    sect = {s: (a, b) for s, a, b in TL.SECTIONS}
    def each_bar(name, fn):
        a, b = sect[name]
        for bar in bars_in(a, b):
            fn(bar, sec(bar * TL.BAR), (bar * TL.BAR - a) / max(1, b - a))
    # A: quarter-note ostinato, root-fifth-third-fifth, and a soft woodblock clock on every beat
    def A(bar, t, p):
        _, ch, bs = PROG[bar % 4]
        for i, n in enumerate((ch[0], ch[2], ch[1], ch[2])):
            add(m, marimba(hz(n), vel=0.8 if i == 0 else 0.55), t + i * BEAT_S, 0.22)
            add(m, woodblock(2200, vel=0.6), t + i * BEAT_S, 0.05)
        add(m, bass(hz(bs)), t, 0.18)
    each_bar("A", A)
    # B: the aid arrives -- 8th-note arpeggios and bass; a glock chime on each split strip
    def B(bar, t, p):
        _, ch, bs = PROG[bar % 4]
        seq = ch + ch[::-1]
        for i, n in enumerate(seq):
            add(m, marimba(hz(n), 0.6, 0.85 if i % 4 == 0 else 0.6), t + i * BEAT_S / 2, 0.2)
        add(m, bass(hz(bs)), t, 0.25)
        add(m, bass(hz(bs)), t + 2 * BEAT_S, 0.18)
    each_bar("B", B)
    for _, d in TL.SPLIT_STRIPS:
        add(m, glock(hz("A5")), sec(TL.START["SPLIT"] + d), 0.18)
    # C: midnight -- one vibraphone dyad per bar
    def C(bar, t, p):
        _, ch, bs = PROG[bar % 4]
        add(m, vibe(hz(ch[0])), t, 0.18); add(m, vibe(hz(ch[2])), t + BEAT_S * 2, 0.12)
    each_bar("C", C)
    # D: step by step -- each chat bubble plays the next note up; a soft dyad per bar underneath
    def D(bar, t, p):
        _, ch, bs = PROG[bar % 4]
        add(m, vibe(hz(ch[0]), 2.0), t, 0.1)
    each_bar("D", D)
    up = ["D5", "F5", "G5", "A5"]
    k = 0
    for e in events:
        if e["kind"] == "bubble":
            add(m, marimba(hz(up[k % 4]), 1.0, 1.0), e["t"], 0.3); k += 1
        if e["kind"] == "solved":
            for i, n in enumerate(("D5", "F#5", "A5", "D6")):
                add(m, glock(hz(n)), e["t"] + i * 0.06, 0.16)
    # E: morning to class -- full ensemble, building
    def E(bar, t, p):
        _, ch, bs = PROG[bar % 4]
        g = 0.55 + 0.45 * p
        for i, n in enumerate(ch + ch[::-1]):
            add(m, marimba(hz(n), 0.6, 0.85 if i % 4 == 0 else 0.6), t + i * BEAT_S / 2, 0.2 * g)
        add(m, bass(hz(bs)), t, 0.28 * g); add(m, bass(hz(bs)), t + 2 * BEAT_S, 0.2 * g)
        for i, n in enumerate(MOTIF[bar % 4]):
            add(m, glock(hz(n)), t + i * 2 * BEAT_S, 0.12 * g)
    each_bar("E", E)
    # F: resolution -- full theme; the last chord rings on the notebook's tick
    def F(bar, t, p):
        _, ch, bs = PROG[bar % 4]
        for i, n in enumerate(ch + ch[::-1]):
            add(m, marimba(hz(n), 0.6, 0.8 if i % 4 == 0 else 0.55), t + i * BEAT_S / 2, 0.2)
        add(m, bass(hz(bs)), t, 0.28)
        for i, n in enumerate(MOTIF[bar % 4]):
            add(m, glock(hz(n)), t + i * 2 * BEAT_S, 0.16)
    a, b = sect["F"]
    tick = next((e["t"] for e in events if e["kind"] == "tick_mark"), sec(b))
    for bar in bars_in(a, b):
        if sec(bar * TL.BAR) < tick - 0.05:
            F(bar, sec(bar * TL.BAR), 0)
    for n in ("D3", "A3", "D4", "F4", "A4", "D5"):
        add(m, vibe(hz(n), 4.0), tick, 0.12)
    add(m, glock(hz("D6"), 3.0), tick, 0.15)
    # G: end card -- the motif on a music box, then out
    a, b = sect["G"]
    for i, n in enumerate(["A5", "F5", "G5", "D5", "F5", "E5", "D5"]):
        add(m, musicbox(hz(n)), sec(a) + 0.3 + i * BEAT_S * 1.5, 0.14)
    # hard silences: nothing from the score inside S1 or S2
    for s in ("S1", "S2"):
        a, b = sect[s]
        i0, i1 = int(sec(a) * SR), int(sec(b) * SR)
        fade = int(0.08 * SR)
        m[i0:i0 + fade] *= np.linspace(1, 0, fade)
        m[i0 + fade:i1] = 0
    m[int(sec(TL.START["b14"]) * SR):] *= 0      # "like, share, follow" is voice only
    return m

# ---------------------------------------------------------------- foley
def noise(d):
    return rng.standard_normal(int(d * SR))

def fx(kind):
    if kind == "pop":
        t, e = env(0.06, 0.001, 60)
        return 0.5 * np.sin(2 * np.pi * (900 - 3000 * t) * t) * e + 0.05 * hp(noise(0.06), 3000) * e
    if kind in ("swish", "swish_soft"):
        d = 0.32
        x = bp(noise(d), 500, 3500) * np.sin(np.linspace(0, np.pi, int(d * SR))) ** 2
        return x * (0.35 if kind == "swish" else 0.2)
    if kind == "tick":
        return woodblock(3200, 0.03, 0.5)
    if kind in ("scratch", "tick_mark"):
        d = 0.45 if kind == "scratch" else 0.18
        x = hp(noise(d), 2500) * (0.6 + 0.4 * np.sin(2 * np.pi * 14 * t_arr(d)) ** 2)
        return 0.18 * x * np.sin(np.linspace(0, np.pi, len(x)))
    if kind in ("type", "key", "tap"):
        t, e = env(0.02, 0.0005, 300)
        return (0.25 if kind != "tap" else 0.18) * hp(noise(0.02), 1500) * e
    if kind == "click":
        a = fx("type")
        out = np.zeros(int(0.12 * SR)); out[:len(a)] += a * 1.6; out[int(0.07 * SR):int(0.07 * SR) + len(a)] += a
        return out
    if kind == "chime":       # the aid's signature: three rising glock notes
        out = np.zeros(int(1.8 * SR))
        for i, n in enumerate(("D6", "F6", "A6")):
            g = glock(hz(n), 1.4)
            j = int(i * 0.09 * SR); out[j:j + len(g)] += g
        return 0.3 * out
    if kind == "page":
        d = 0.35
        return 0.2 * bp(noise(d), 1500, 7000) * np.exp(-t_arr(d) * 8)
    if kind == "bubble":
        t, e = env(0.08, 0.002, 40)
        return 0.15 * np.sin(2 * np.pi * 1400 * t) * e
    if kind == "solved":
        return 0.0 * np.zeros(10)
    if kind == "step":
        t, e = env(0.09, 0.001, 45)
        return 0.4 * (np.sin(2 * np.pi * 85 * t) + 0.4 * lp(noise(0.09), 900)) * e
    if kind == "marker":
        d = 0.3
        t = t_arr(d)
        return 0.06 * np.sin(2 * np.pi * (2400 + 300 * np.sin(2 * np.pi * 9 * t)) * t) * np.sin(np.linspace(0, np.pi, len(t)))
    if kind == "reveal":
        return np.zeros(10)
    raise ValueError(f"no foley for kind {kind!r}")

def build_foley(events):
    f = np.zeros(N)
    unknown = set()
    for e in events:
        try:
            add(f, fx(e["kind"]), e["t"])
        except ValueError:
            unknown.add(e["kind"])      # one unknown kind never stops the mix; it is reported
    return f, sorted(unknown)

# ---------------------------------------------------------------- ambience
def bed(kind, d):
    n = noise(d)
    t = t_arr(d)
    if kind in ("class", "desk", "room", "library"):
        tone = lp(n, 350) * db(-34)
        mur = bp(noise(d), 300, 1400) * (0.5 + 0.5 * np.sin(2 * np.pi * 0.31 * t) * np.sin(2 * np.pi * 0.17 * t)) * db(-44)
        return tone + (mur if kind == "class" else 0) * 1.0 * (kind != "library")
    if kind == "corridor":
        x = lp(n, 500) * db(-32) + bp(noise(d), 300, 2000) * db(-38) * (0.6 + 0.4 * np.sin(2 * np.pi * 0.23 * t))
        for s in np.arange(0.4, d, 0.55):
            add(x, fx("step") * 0.15, s)
        return x
    if kind == "mrt":
        x = lp(np.cumsum(n) / 300, 150) * db(-14) + np.sin(2 * np.pi * 110 * t) * db(-46)
        for s in np.arange(0.2, d, 1.1):
            add(x, woodblock(300, 0.08, 0.5), s); add(x, woodblock(280, 0.08, 0.4), s + 0.16)
        return x
    if kind == "night":
        x = lp(n, 200) * db(-40) + np.sin(2 * np.pi * 60 * t) * db(-54)
        for s in np.arange(0.5, d, 0.9):
            c = np.sin(2 * np.pi * 4300 * t_arr(0.05)) * np.hanning(int(0.05 * SR))
            add(x, c * db(-46), s); add(x, c * db(-48), s + 0.09)
        return x
    if kind == "screen":
        return np.sin(2 * np.pi * 100 * t) * db(-50) + lp(n, 300) * db(-42)
    if kind == "staff":
        x = lp(n, 350) * db(-36)
        for s in rng.uniform(0, d, int(d * 1.4)):
            dd = 0.12
            tt = t_arr(dd)
            add(x, np.sin(2 * np.pi * (3200 + 1500 * tt / dd) * tt) * np.hanning(len(tt)) * db(-34), s)
        return x
    raise ValueError(kind)

def build_amb():
    a = np.zeros(N)
    for kind, f0, f1 in TL.AMB:
        d = sec(f1 - f0)
        x = bed(kind, d)
        fade = min(int(0.2 * SR), len(x) // 2)
        x[:fade] *= np.linspace(0, 1, fade); x[-fade:] *= np.linspace(1, 0, fade)
        add(a, x, sec(f0))
    return a

# ---------------------------------------------------------------- voice
def load(path):
    raw = subprocess.run([FF, "-v", "error", "-i", path, "-ac", "1", "-ar", str(SR), "-f", "f32le", "-"],
                         capture_output=True, check=True).stdout
    return np.frombuffer(raw, np.float32).astype(np.float64)

def vo_starts():
    words = json.load(open(os.path.join(VO, "words.json"), encoding="utf-8"))
    st = {}
    for n, (beat, bt) in TL.VO_AT.items():
        st[n] = sec(TL.frame_of(beat, bt, TL.VO_LEAD))
    for n, (word, beat, bt) in TL.VO_ANCHOR.items():
        w = next(x for x in words[str(n)]["words"] if x["w"].lower().strip(".,!?") == word)
        st[n] = sec(TL.frame_of(beat, bt)) - w["start"]
    return st

def build_vo(starts):
    v = np.zeros(N)
    for n, t in starts.items():
        add(v, load(os.path.join(VO, f"vo{n:02d}.mp3")), t)
    return v

# ---------------------------------------------------------------- events from the beats
def gather_events():
    evs, missing = [], []
    for beat, _ in TL.ORDER:
        parts = [(beat, 0)] if beat != "SPLIT" else [(s, d) for s, d in TL.SPLIT_STRIPS]
        for b, delay in parts:
            p = os.path.join(FR, b, "events.json")
            if not os.path.exists(p):
                missing.append(b)
                continue
            for e in json.load(open(p))["events"]:
                fr = TL.START[beat] + delay + e["f"] - 1
                evs.append(dict(e, beat=b, frame=fr, t=sec(fr)))
    return sorted(evs, key=lambda e: e["t"]), missing

def cuecheck(evs, starts):
    """Every key action should sit on a beat (15 f); voice lines must not overlap."""
    off = [e for e in evs if e["kind"] in ("pop", "bubble", "solved", "chime", "step", "scratch", "marker", "tick_mark", "click")
           and (e["frame"] % TL.BEAT) not in (0, 14)]
    order = sorted(starts.items(), key=lambda kv: kv[1])
    overlaps = []
    for (a, ta), (b, tb) in zip(order, order[1:]):
        end = ta + dur(os.path.join(VO, f"vo{a:02d}.mp3"))
        if end > tb - 0.05:
            overlaps.append((a, b, round(end - tb, 2)))
    return off, overlaps

def main():
    evs, missing = gather_events()
    starts = vo_starts()
    music = build_music(evs)
    foley, unknown = build_foley(evs)
    amb = build_amb()
    vo = build_vo(starts)
    # duck the music 8 dB under the voice (envelope smoothed over 0.25 s)
    e = np.abs(vo)
    k = int(0.25 * SR)
    e = np.convolve(e, np.ones(k) / k, mode="same")
    duck = 1 - (1 - db(-8)) * np.clip(e / (e.max() * 0.15 + 1e-9), 0, 1)
    mix = music * duck + foley + amb + vo * 0.9
    peak = np.abs(mix).max()
    for name, x in (("music", music), ("foley", foley), ("amb", amb), ("vo", vo), ("mix", mix / peak * 0.89)):
        x = np.clip(x, -1, 1).astype(np.float32)
        subprocess.run([FF, "-y", "-v", "error", "-f", "f32le", "-ar", str(SR), "-ac", "1", "-i", "-",
                        os.path.join(OUT, f"{name}.wav")], input=x.tobytes(), check=True)
    off, overlaps = cuecheck(evs, starts)
    json.dump({"vo_starts": starts, "events": evs}, open(os.path.join(OUT, "cues.json"), "w"), indent=1)
    sil = {s: float(np.abs(music[int(sec(a) * SR) + int(0.1 * SR):int(sec(b) * SR)]).max())
           for s, a, b in TL.SECTIONS if s in ("S1", "S2")}
    print(f"SOUND events={len(evs)} missing_beats={missing} unknown_kinds={unknown}")
    print(f"SOUND off_grid={[(e['beat'], e['kind'], e['frame']) for e in off]}")
    print(f"SOUND vo_overlaps={overlaps}  silence_peaks={sil}")
    print("SOUND vo starts", {n: round(t, 2) for n, t in sorted(starts.items())})

if __name__ == "__main__":
    main()

