sys.modules["timeline"] = TL          # sound.py reads `timeline`; point it at v4 before importing it
import sound as S
from sound import add, db, hz, marimba, glock, vibe, bass, musicbox, woodblock, lp, hp, bp, noise, t_arr, env, sec, SR
from vo_tools import dur

S.FR = os.path.join(HERE, "frames_v4")
S.OUT = os.path.join(HERE, "audio_v4")
os.makedirs(S.OUT, exist_ok=True)
N = S.N
FOLEY_MAX_HZ = 2000

# ---------------------------------------------------------------- foley: low, soft, never on top of a word
def fx(kind):
    if kind == "pop":
        t, e = env(0.08, 0.002, 45)
        return 0.12 * np.sin(2 * np.pi * (520 - 600 * t) * t) * e
    if kind == "drop":
        t, e = env(0.14, 0.001, 30)
        return 0.32 * (np.sin(2 * np.pi * 140 * t) + 0.3 * lp(noise(0.14), 400)) * e
    if kind in ("click", "key", "tap"):
        t, e = env(0.025, 0.0005, 220)
        a = 0.14 * lp(noise(0.025), 1500) * e
        if kind != "click":
            return a
        out = np.zeros(int(0.1 * SR)); out[:len(a)] += a; out[int(0.06 * SR):int(0.06 * SR) + len(a)] += 0.7 * a
        return out
    if kind == "ready":                 # the tutor is ready: three soft, low notes
        out = np.zeros(int(1.6 * SR))
        for i, n in enumerate(("D5", "F5", "A5")):
            g = lp(glock(hz(n), 1.3), 1800)
            j = int(i * 0.1 * SR); out[j:j + len(g)] += g
        return 0.1 * out
    if kind == "posted":
        return 0.08 * lp(marimba(hz("A4"), 0.6), 1800)
    if kind == "bubble":
        t, e = env(0.09, 0.002, 35)
        return 0.1 * np.sin(2 * np.pi * 600 * t) * e
    if kind == "hinge":
        d = 0.25
        return 0.07 * lp(noise(d), 600) * np.sin(np.linspace(0, np.pi, int(d * SR)))
    if kind in ("rustle", "page"):
        d = 0.3
        return (0.05 if kind == "rustle" else 0.09) * lp(bp(noise(d), 300, 1800), 1800) * np.sin(np.linspace(0, np.pi, int(d * SR)))
    if kind == "step":
        t, e = env(0.09, 0.001, 45)
        return 0.22 * (np.sin(2 * np.pi * 85 * t) + 0.4 * lp(noise(0.09), 700)) * e
    if kind in ("reveal", "solved"):
        return np.zeros(10)
    raise ValueError(f"no foley for kind {kind!r}")

# ---------------------------------------------------------------- ambience (birds and crickets kept low and quiet)
def bed(kind, d):
    n, t = noise(d), t_arr(d)
    if kind == "staff":
        x = lp(n, 350) * db(-36)
        for s in S.rng.uniform(0, d, int(d * 1.2)):
            tt = t_arr(0.12)
            add(x, np.sin(2 * np.pi * (1800 + 700 * tt / 0.12) * tt) * np.hanning(len(tt)) * db(-46), s)
        return x
    if kind == "night":
        return lp(n, 200) * db(-40) + np.sin(2 * np.pi * 60 * t) * db(-54)
    if kind == "staff_eve":
        return lp(n, 300) * db(-38) + np.sin(2 * np.pi * 100 * t) * db(-52)
    return _bed0(kind, d)
_bed0 = S.bed

# ---------------------------------------------------------------- voice from timeline_v4
def vo_starts():
    return {n: TL.vo_start_frame(n) / TL.FPS for n in TL.VO_TEXT}

def build_vo(starts):
    v = np.zeros(N)
    for n, t in starts.items():
        add(v, S.load(TL.vo_file(n)), t)
    return v

def cuecheck(evs, starts):
    order = sorted(starts.items(), key=lambda kv: kv[1])
    overlaps = []
    for (a, ta), (b, tb) in zip(order, order[1:]):
        end = ta + dur(TL.vo_file(a))
        if end > tb - 0.05:
            overlaps.append((a, b, round(end - tb, 2)))
    off = [e for e in evs if e["kind"] in ("pop", "drop", "bubble", "step") and (e["frame"] % TL.BEAT) not in (0, 14)]
    return off, overlaps

# ---------------------------------------------------------------- score
BEAT_S = 60 / TL.BPM
PROG, MOTIF = S.PROG, S.MOTIF

def build_music(events):
    m = np.zeros(N)
    sect = {s: (a, b) for s, a, b in TL.SECTIONS}
    def each_bar(name, fn):
        a, b = sect[name]
        for bar in S.bars_in(a, b):
            fn(bar, sec(bar * TL.BAR), (bar * TL.BAR - a) / max(1, b - a))
    def sparse(bar, t, p):              # A: the miss -- low root and fifth, a soft low clock
        _, ch, bs = PROG[bar % 4]
        add(m, marimba(hz(ch[0]) / 2, 1.2, 0.8), t, 0.2); add(m, marimba(hz(ch[2]) / 2, 1.2, 0.6), t + 2 * BEAT_S, 0.16)
        for i in range(4):
            add(m, lp(woodblock(900, 0.05, 0.6), 1500), t + i * BEAT_S, 0.05)
    each_bar("A1", sparse)
    each_bar("A2", lambda bar, t, p: (sparse(bar, t, p), add(m, bass(hz(PROG[bar % 4][2])), t, 0.15)))
    def pulse(bar, t, p, g=1.0):        # B/C: the pulse, 8th-note arpeggios
        _, ch, bs = PROG[bar % 4]
        for i, n in enumerate(ch + ch[::-1]):
            add(m, marimba(hz(n), 0.6, 0.85 if i % 4 == 0 else 0.6), t + i * BEAT_S / 2, 0.18 * g)
        add(m, bass(hz(bs)), t, 0.24 * g); add(m, bass(hz(bs)), t + 2 * BEAT_S, 0.17 * g)
    each_bar("B", lambda bar, t, p: pulse(bar, t, p, 0.7 + 0.3 * p))
    each_bar("C", pulse)
    for _, d in TL.SPLIT_STRIPS:
        add(m, glock(hz("A5")), sec(TL.START["SPLIT"] + d), 0.06)
    def night(bar, t, p):               # D: midnight
        _, ch, bs = PROG[bar % 4]
        add(m, vibe(hz(ch[0])), t, 0.16); add(m, vibe(hz(ch[2])), t + BEAT_S * 2, 0.11)
    each_bar("D", night)
    up, k = ["D5", "F5", "G5", "A5", "C6"], 0
    for e in events:
        if e["kind"] == "bubble" and TL.START["h5c"] <= e["frame"] < TL.START["h6"]:
            add(m, marimba(hz(up[k % 5]), 1.0, 1.0), e["t"], 0.26); k += 1
        if e["kind"] == "solved":
            for i, n in enumerate(("D5", "F#5", "A5", "D6")):
                add(m, glock(hz(n)), e["t"] + i * 0.06, 0.13)
    def build(bar, t, p, g0=0.55):      # E: morning to class, building
        g = g0 + (1 - g0) * p
        pulse(bar, t, p, g)
        for i, n in enumerate(MOTIF[bar % 4]):
            add(m, glock(hz(n)), t + i * 2 * BEAT_S, 0.1 * g)
    each_bar("E", build)
    # F: this time -- the theme returns under Maya's line, then G: loud and full under the action
    a, b = sect["F"]
    for n in ("D3", "A3", "D4", "F4", "A4"):
        add(m, vibe(hz(n), 3.5), sec(a), 0.1)
    each_bar("F", lambda bar, t, p: build(bar, t, p, 0.8))
    a, b = sect["G"]
    last = None
    for bar in S.bars_in(a, b - TL.BAR // 2):
        build(bar, sec(bar * TL.BAR), 1.0, 1.0)
        add(m, bass(hz(PROG[bar % 4][2]) * 2), sec(bar * TL.BAR) + BEAT_S, 0.12)
        last = bar
    end = sec((last + 1) * TL.BAR) if last is not None else sec(b)
    for n in ("D3", "A3", "D4", "F4", "A4", "D5"):          # the final chord lands on a downbeat
        add(m, vibe(hz(n), 3.0), end, 0.14)
    add(m, glock(hz("D6"), 2.5), end, 0.12)
    for s in ("S1", "S2"):                                  # hard silences: no score inside S1 or S2
        a, b = sect[s]
        i0, i1 = int(sec(a) * SR), int(sec(b) * SR)
        fade = int(0.08 * SR)
        m[i0:i0 + fade] *= np.linspace(1, 0, fade)
        m[i0 + fade:i1] = 0
    return m * db(2)                                        # the score sits a little louder than v3 under the ducking

def foley_check(foley, vo):
    """Teacher's comment: no piercing foley. Share of foley energy above 2 kHz, and the loudest foley vs the voice."""
    hi = hp(foley, FOLEY_MAX_HZ, 4)
    ratio = float(np.sum(hi ** 2) / max(1e-12, np.sum(foley ** 2)))
    band = hp(foley, 300)                                   # phone-speaker band
    win = int(0.2 * SR)
    peak = max(float(np.sqrt(np.mean(band[i:i + win] ** 2))) for i in range(0, len(band) - win, win))
    v = vo[np.abs(vo) > 1e-4]
    vrms = float(np.sqrt(np.mean(v ** 2))) if len(v) else 1.0
    return ratio, 20 * np.log10(max(peak, 1e-9) / vrms)

S.fx, S.bed, S.vo_starts, S.build_vo, S.cuecheck, S.build_music = fx, bed, vo_starts, build_vo, cuecheck, build_music

def main():
    S.main()
    import subprocess
    from vo_tools import FF
    def rd(name):
        raw = subprocess.run([FF, "-v", "error", "-i", os.path.join(S.OUT, name), "-f", "f32le", "-"], capture_output=True, check=True).stdout
        return np.frombuffer(raw, np.float32).astype(np.float64)
    ratio, loud = foley_check(rd("foley.wav"), rd("vo.wav"))
    print(f"SOUND foley energy above {FOLEY_MAX_HZ} Hz: {ratio * 100:.2f}% (want < 2%); loudest foley vs voice "
          f"(phone band): {loud:.1f} dB (want <= -15)")

if __name__ == "__main__":
    main()

