        add(m, bass(hz(bs)), t, 0.24 * g); add(m, bass(hz(bs)), t + 2 * BEAT_S, 0.17 * g)
    each_bar("B", lambda bar, t, p: pulse(bar, t, p, 0.7 + 0.3 * p))
    each_bar("C", pulse)
    for _, d in TL.SPLIT_STRIPS:
        add(m, glock(hz("A5")), sec(TL.START["SPLIT"] + d), 0.06)
    # the chat stays calm (user, 2026-11-24): no note per bubble. The "Solved it!" chord waits for the first bar
    # after Maya's line ends, and that bar's own notes are left out, so the chord sounds in a gap, not on a beat
    solved = next((e["t"] for e in events if e["kind"] == "solved"), None)
    chord_bar = None
    if solved is not None:
        v7_end = TL.vo_start_frame(7) / TL.FPS + dur(TL.vo_file(7))
        chord_bar = int(np.ceil(max(solved, v7_end + 0.15) * TL.FPS / TL.BAR))
        for n in ("D4", "F#4", "A4"):
